fn len_of(xs: List[Int]) -> Int
  requires (len(xs) >= 0)
  ensures (result == len(xs))
  effects pure
  example (len_of([]) == 0)
  example (len_of([4, 5]) == 2)
{
  match xs { [] => 0 [_, ..t] => (1 + len_of(t)) }
}

fn count_in(xs: List[Int], x: Int) -> Int
  requires (len(xs) >= 0)
  ensures (result == count(xs, x))
  effects pure
  example (count_in([3, 1, 3], 3) == 2)
  example (count_in([], 3) == 0)
  example (count_in([1, 2], 3) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h == x) then (1 + count_in(t, x)) else count_in(t, x) }
}

fn first_major(xs: List[Int], ys: List[Int]) -> Option[Int]
  requires (len(xs) >= 0)
  ensures match result { Some(v) => (contains(ys, v) and ((count(xs, v) * 2) > len(xs))) None => forall y in ys: ((count(xs, y) * 2) <= len(xs)) }
  effects pure
  example (first_major([3, 1, 3, 3], [3, 1, 3, 3]) == Some(3))
  example (first_major([1, 2], [1, 2]) == None)
  example (first_major([], []) == None)
{
  match ys { [] => None [h, ..t] => if ((count_in(xs, h) * 2) > len_of(xs)) then Some(h) else first_major(xs, t) }
}

fn majority(xs: List[Int]) -> Option[Int]
  requires (len(xs) >= 0)
  ensures match result { Some(v) => ((count(xs, v) * 2) > len(xs)) None => forall x in xs: ((count(xs, x) * 2) <= len(xs)) }
  effects pure
  example (majority([3, 1, 3, 3]) == Some(3))
  example (majority([1, 2]) == None)
  example (majority([]) == None)
  example (majority([5]) == Some(5))
  example (majority([1, 1, 2, 2]) == None)
  example (majority([2, 1, 2]) == Some(2))
{
  first_major(xs, xs)
}

